async function seed() {
  const col = db.collection('scienceQuestions')
  const BATCH_SIZE = 499
  let count = 0
  for (let i = 0; i < questions.length; i += BATCH_SIZE) {
    const batch = db.batch()
    for (const q of questions.slice(i, i + BATCH_SIZE)) { batch.set(col.doc(), q); count++ }
    await batch.commit()
    console.log(`  Committed batch up to question ${count}`)
  }
  const grades = ['7','8']
  grades.forEach(g => console.log(`   Grade ${g}: ${questions.filter(q=>q.grade===g).length}/150 questions`))
  console.log(`\n✅ Seeded ${count} questions (grades 7–8). Run seed-science-grade9-12.cjs for grades 9–12.`)
}
seed().catch(e => { console.error(e); process.exit(1) })
